/**
 * Record types for the internal workspace.
 *
 * Records are plain data. Fields are documented so callers know what may be
 * empty and what is validated by the store.
 *
 * Names must be nonblank. Descriptive fields are text and may be empty.
 * Parent links are set at creation time and are immutable afterwards.
 */

/** A client workspace record. */
export interface Client {
  /** Stable identifier generated by the store. */
  readonly id: string;
  /** Display name. Must be nonblank. */
  readonly name: string;
  /** Background text. May be empty. */
  readonly background: string;
  /** Contacts text. May be empty. */
  readonly contacts: string;
  /** Stakeholders text. May be empty. */
  readonly stakeholders: string;
  /** Requirements text. May be empty. */
  readonly requirements: string;
  /** Objectives text. May be empty. */
  readonly objectives: string;
}

/** A client engagement record. */
export interface Engagement {
  /** Stable identifier generated by the store. */
  readonly id: string;
  /** Parent client id. Immutable after creation. */
  readonly clientId: string;
  /** Display name. Must be nonblank. */
  readonly name: string;
  /** Objectives text. May be empty. */
  readonly objectives: string;
  /** Lifecycle status. */
  readonly status: Status;
}

/** A project within an engagement. */
export interface Project {
  /** Stable identifier generated by the store. */
  readonly id: string;
  /** Parent engagement id. Immutable after creation. */
  readonly engagementId: string;
  /** Display name. Must be nonblank. */
  readonly name: string;
  /** Objectives text. May be empty. */
  readonly objectives: string;
  /** Lifecycle status. */
  readonly status: Status;
}

/** Lifecycle status for engagements and projects. */
export type Status = "planned" | "active" | "on_hold" | "completed";

/** The set of permitted status values. */
export const STATUSES: readonly Status[] = ["planned", "active", "on_hold", "completed"];

/** Input for creating a client. Descriptive fields default to empty text. */
export interface ClientInput {
  name: string;
  background?: string;
  contacts?: string;
  stakeholders?: string;
  requirements?: string;
  objectives?: string;
}

/** Input for editing a client. The name is optional; omitted fields are kept. */
export interface ClientUpdate {
  name?: string;
  background?: string;
  contacts?: string;
  stakeholders?: string;
  requirements?: string;
  objectives?: string;
}

/** Input for creating an engagement. */
export interface EngagementInput {
  clientId: string;
  name: string;
  objectives?: string;
  status?: Status;
}

/** Input for editing an engagement. Parent links are immutable; all fields optional. */
export interface EngagementUpdate {
  name?: string;
  objectives?: string;
  status?: Status;
}

/** Input for creating a project. */
export interface ProjectInput {
  engagementId: string;
  name: string;
  objectives?: string;
  status?: Status;
}

/** Input for editing a project. Parent links are immutable; all fields optional. */
export interface ProjectUpdate {
  name?: string;
  objectives?: string;
  status?: Status;
}

/** A detached, read-only snapshot of the whole workspace. */
export interface WorkspaceSnapshot {
  readonly clients: readonly Client[];
  readonly engagements: readonly Engagement[];
  readonly projects: readonly Project[];
}

/**
 * Error kinds callers can distinguish.
 *
 * `persistence` covers I/O failures while reading or writing, including
 * existing data that is corrupt, unsupported or invalid: such data is refused
 * and left untouched rather than reported as a missing record.
 */
export type StoreErrorKind =
  | "validation"
  | "missing"
  | "busy"
  | "persistence";

/** Base class for all store errors; carries a discriminated `kind`. */
export class StoreError extends Error {
  readonly kind: StoreErrorKind;
  constructor(kind: StoreErrorKind, message: string) {
    super(message);
    this.name = "StoreError";
    this.kind = kind;
  }
}

/** A record or input failed validation, or a parent reference is invalid. */
export class ValidationError extends StoreError {
  constructor(message: string) {
    super("validation", message);
    this.name = "ValidationError";
  }
}

/** A referenced record does not exist. */
export class MissingRecordError extends StoreError {
  constructor(message: string) {
    super("missing", message);
    this.name = "MissingRecordError";
  }
}

/** Another store instance owns this data directory. */
export class BusyStoreError extends StoreError {
  constructor(message: string) {
    super("busy", message);
    this.name = "BusyStoreError";
  }
}

/**
 * Reading or writing state failed; the previous committed state is retained.
 *
 * Covers I/O failures and existing data that is corrupt, unsupported or
 * invalid, which is refused without being overwritten.
 */
export class PersistenceError extends StoreError {
  constructor(message: string, options?: { cause?: unknown }) {
    super("persistence", message);
    this.name = "PersistenceError";
    if (options && "cause" in options) {
      (this as { cause?: unknown }).cause = options.cause;
    }
  }
}

